export function calculateOrderTotal(unitPrices: number[], discountRate: number): number {
    const subtotal = unitPrices.reduce((sum, price) => sum + price, 0);
    return Math.round(subtotal * (1 - discountRate) * 100) / 100;
}

import { calculateOrderTotal } from './pricing';

export function submitOrder(orderId: string, unitPrices: number[], discountRate: number): string {
    const total = calculateOrderTotal(unitPrices, discountRate);
    return `${orderId}:accepted:${total.toFixed(2)}`;
}
